import { z } from 'zod';

/**
 * Claude Code accounts (ADR 0021, wiki claude-accounts.md). Each extra account is a separate
 * `CLAUDE_CONFIG_DIR` that main derives from the id (`<userData>/claude-accounts/<id>`); the
 * renderer never sends a path. The "default" account is the CLI's own config (no override).
 * oIDE never reads what the CLI writes in those folders (credentials stay the CLI's).
 */

/** Generated by main (`acc-` + random): safe as a folder name, never equal to `default`. */
export const AccountId = z.string().regex(/^acc-[a-z0-9]{6,32}$/, 'Not a valid account id');
export type AccountId = z.infer<typeof AccountId>;

/** The CLI's own config, used when an agent has no `accountId`. */
export const DEFAULT_ACCOUNT = 'default' as const;

/** An account id, or `default` for the CLI's own config. */
export const AccountKey = z.union([z.literal(DEFAULT_ACCOUNT), AccountId]);
export type AccountKey = z.infer<typeof AccountKey>;

export const ACCOUNT_LABEL_MAX = 40;
export const AccountLabel = z.string().trim().min(1, 'Give the account a name').max(ACCOUNT_LABEL_MAX);

export const ClaudeAccount = z.object({
  id: AccountId,
  label: AccountLabel,
});
export type ClaudeAccount = z.infer<typeof ClaudeAccount>;

/** `settings.accounts`. Defaulted as a whole so older settings files parse. */
export const AccountsSettings = z
  .object({
    /** Name shown for the CLI's own config once there is more than one account. */
    defaultLabel: AccountLabel.default('Default'),
    list: z.array(ClaudeAccount).max(16).default([]),
    /** Account Spawn picks first. Unset, or an id that no longer exists, means the default account. */
    spawnDefault: AccountKey.optional(),
  })
  .default({ defaultLabel: 'Default', list: [] });
export type AccountsSettings = z.infer<typeof AccountsSettings>;

/** One plan window as the CLI last reported it in a `rate_limit_event` (ADR 0007). */
export const PlanWindowUsage = z.object({
  /** `five_hour`, `seven_day`, `seven_day_opus`…; `plan` when the CLI named none. */
  window: z.string().min(1).max(64),
  status: z.string().max(64),
  /** 0..1 when the CLI reported it; never guessed. */
  utilization: z.number().min(0).max(10).optional(),
  resetsAt: z.number().optional(),
  /** When oIDE saw it (ms). Old values are shown with their age, and hidden once `resetsAt` passed. */
  seenAt: z.number(),
});
export type PlanWindowUsage = z.infer<typeof PlanWindowUsage>;

/** What the status bar shows per account. Built in main from agent events; persisted across restarts. */
export const AccountUsage = z.object({
  accountId: AccountKey,
  label: z.string(),
  /** Learned from agents on this account: init → yes, auth error → no. */
  signedIn: z.enum(['yes', 'no', 'unknown']),
  windows: z.array(PlanWindowUsage).max(16),
  /** Set while an agent on this account is rate-limited (the reset time the CLI gave). */
  rateLimitedUntil: z.number().optional(),
  /** Tokens used today by agents on this account (cache included). */
  tokensToday: z.number().int().nonnegative(),
});
export type AccountUsage = z.infer<typeof AccountUsage>;

/** All accounts: the default one first, then Settings order. */
export function accountKeys(s: AccountsSettings): AccountKey[] {
  return [DEFAULT_ACCOUNT, ...s.list.map((a) => a.id)];
}

/** The label of an account key; `undefined` when the id is not configured any more. */
export function accountLabel(s: AccountsSettings, key: AccountKey | undefined): string | undefined {
  if (!key || key === DEFAULT_ACCOUNT) return s.defaultLabel;
  return s.list.find((a) => a.id === key)?.label;
}

/** The account Spawn should pick first: `spawnDefault` when it still exists, else the default account. */
export function spawnDefaultAccount(s: AccountsSettings): AccountKey {
  const k = s.spawnDefault;
  return k && k !== DEFAULT_ACCOUNT && s.list.some((a) => a.id === k) ? k : DEFAULT_ACCOUNT;
}

/** Windows still worth showing at `now`: a utilization whose reset time passed says nothing any more. */
export function liveWindows(windows: readonly PlanWindowUsage[], now: number): PlanWindowUsage[] {
  return windows.filter((w) => w.resetsAt === undefined || w.resetsAt > now);
}

/** The window closest to its limit (highest reported utilization), for a one-number summary. */
export function tightestWindow(windows: readonly PlanWindowUsage[], now: number): PlanWindowUsage | undefined {
  let best: PlanWindowUsage | undefined;
  for (const w of liveWindows(windows, now)) {
    if (typeof w.utilization !== 'number') continue;
    if (!best || w.utilization > (best.utilization ?? -1)) best = w;
  }
  return best;
}
